<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {command,message} from '../api'
import {useDatabase} from '../stores/database'
import type {FieldDefinition} from '../types'
interface Option{value:string;label:string;baseValue:string;hidden:boolean}
interface Settings{id:number;revision:number;name:string;code:string;formCode:string;version:string;hidden:boolean;gender:string;options:Record<string,Option[]>}
interface Preset{key:string;code:string;version:string;definitions:FieldDefinition[]}
const open=defineModel<boolean>('open')
const emit=defineEmits<{changed:[]}>()
const db=useDatabase(),kinds=ref<Settings[]>([]),presets=ref<Preset[]>([]),editing=ref(false),id=ref<number>(),revision=ref(0),name=ref(''),preset=ref(''),hidden=ref(false),gender=ref(''),options=ref<Record<string,Option[]>>({}),field=ref(''),error=ref(''),success=ref(''),busy=ref(false)
const currentPreset=computed(()=>presets.value.find(p=>p.key===preset.value))
const presetItems=computed(()=>presets.value.map(p=>({value:p.key,label:`${p.code==='universal'?'Свободное описание':kinds.value.find(t=>t.code.toLowerCase()===p.code)?.name||p.code} · версия ${p.version}`})))
const fields=computed(()=>(currentPreset.value?.definitions||[]).filter(d=>d.options?.length))
const selectedField=computed(()=>fields.value.find(d=>d.key===field.value))
const rows=computed(()=>options.value[field.value]||[])
async function load(){busy.value=true;error.value='';try{const result=await command<{templates:Settings[];presets:Preset[]}>('catalog_settings');kinds.value=result.templates;presets.value=result.presets}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(load)
function edit(kind?:Settings){id.value=kind?.id;revision.value=kind?.revision||0;name.value=kind?.name||'';preset.value=kind?`${kind.formCode}_${kind.version}`:'universal_1';hidden.value=kind?.hidden||false;gender.value=kind?.gender||'';options.value=structuredClone(kind?JSON.parse(JSON.stringify(kind.options)):{});field.value='';error.value='';success.value='';editing.value=true}
function changePreset(value:string){preset.value=value;options.value={};field.value=''}
function selectField(key:string){field.value=key;if(!options.value[key])options.value[key]=(selectedField.value?.options||[]).map(o=>({value:o.value,label:o.label,baseValue:o.baseValue||o.value,hidden:Boolean(o.hidden)}))}
function add(){const original=selectedField.value?.options?.[0];if(original)rows.value.push({value:'custom_'+crypto.randomUUID(),baseValue:'__text',label:'',hidden:false})}
function reorder(index:number,direction:number){const other=index+direction;if(other<0||other>=rows.value.length)return;[rows.value[index],rows.value[other]]=[rows.value[other],rows.value[index]]}
async function sync(){busy.value=true;error.value='';try{await command('sync_catalog_sections');success.value='Недостающие служебные разделы созданы. Тексты сохранены.';emit('changed')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function save(){const p=currentPreset.value;if(!p)return;busy.value=true;error.value='';try{await command('save_catalog_settings',{input:{id:id.value??null,revision:revision.value,name:name.value,formCode:p.code,version:p.version,hidden:hidden.value,gender:gender.value,options:options.value}});await db.load();await load();if(error.value)return;editing.value=false;success.value='Настройки сохранены. Старые исследования сохраняют прежнюю форму.';emit('changed')}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><UModal v-model:open="open" title="Виды исследований и варианты полей" description="Настройки для новых исследований. Сохранённые протоколы используют свою форму и свои варианты." :dismissible="!busy" :ui="{content:'sm:max-w-4xl'}"><template #body>
<UAlert v-if="error" color="error" :description="error" class="mb-5"/><UAlert v-if="success" color="success" :description="success" class="mb-5"/>
<template v-if="!editing"><div class="flex flex-wrap justify-end gap-3 mb-4"><UButton icon="i-lucide-folder-sync" color="neutral" variant="outline" :disabled="busy" @click="sync">Синхронизировать разделы</UButton><UButton icon="i-lucide-plus" :disabled="busy" @click="edit()">Новый вид исследования</UButton></div><p v-if="busy" role="status">Загружаем настройки…</p><ul class="grid gap-2"><li v-for="kind in kinds" :key="kind.id" class="flex items-center justify-between gap-4 rounded-lg border border-slate-200 p-3"><div><p>{{kind.name}}<span v-if="kind.hidden" class="text-slate-500"> · Скрыт</span></p><p class="text-sm text-slate-500">Версия формы {{kind.version}}</p></div><UButton icon="i-lucide-settings-2" variant="ghost" color="neutral" :disabled="busy" :aria-label="'Настроить: '+kind.name" @click="edit(kind)"/></li></ul></template>
<template v-else><UButton icon="i-lucide-arrow-left" color="neutral" variant="ghost" :disabled="busy" class="mb-4" @click="editing=false">К списку видов</UButton><div class="grid gap-5 md:grid-cols-2"><UFormField label="Название вида исследования" required class="md:col-span-2"><UInput v-model="name" maxlength="200" class="w-full" :disabled="busy"/></UFormField><UFormField label="Форма протокола" required description="Доступны перенесённые формы. Изменение применяется к следующим исследованиям."><USelect :model-value="preset" :items="presetItems" class="w-full" :disabled="busy" @update:model-value="changePreset"/></UFormField><UFormField label="Пол пациента" description="Справочная настройка вида исследования."><USelect v-model="gender" :items="[{label:'Любой',value:''},{label:'Женский',value:'F'},{label:'Мужской',value:'M'}]" class="w-full" :disabled="busy"/></UFormField><UCheckbox v-model="hidden" label="Скрыть для новых исследований" :disabled="busy" :ui="{root:'items-center',container:'h-auto',label:'block'}"/></div>
<section v-if="fields.length" class="mt-7"><h3 class="mb-4">Варианты полей</h3><UFormField label="Поле формы"><USelect :model-value="field" :items="fields.map(d=>({value:d.key,label:[...new Set([d.group,d.label].filter(Boolean))].join(' · ')}))" placeholder="Выберите поле" class="w-full" :disabled="busy" @update:model-value="selectField"/></UFormField><p v-if="field" class="mt-3 text-sm text-slate-500">Собственный текст попадёт в протокол; если исходная форма не выводит это поле, он будет показан отдельным параметром. Можно также выбрать поведение исходного варианта. Исходные варианты доступны для скрытия и восстановления.</p><ul class="grid gap-3 mt-4"><li v-for="(option,index) in rows" :key="option.value" class="rounded-lg border border-slate-200 p-3"><div class="flex gap-2 items-center"><UFormField label="Название в списке" class="flex-1"><UInput v-model="option.label" maxlength="500" class="w-full" :disabled="busy"/></UFormField><UButton icon="i-lucide-arrow-up" variant="ghost" color="neutral" aria-label="Поднять вариант" :disabled="busy||index===0" @click="reorder(index,-1)"/><UButton icon="i-lucide-arrow-down" variant="ghost" color="neutral" aria-label="Опустить вариант" :disabled="busy||index===rows.length-1" @click="reorder(index,1)"/></div><UFormField v-if="option.value.startsWith('custom_')" label="Поведение в протоколе" class="mt-3"><USelect v-model="option.baseValue" :items="[{label:'Собственный текст',value:'__text'},...selectedField?.options||[]]" class="w-full" :disabled="busy"/></UFormField><UCheckbox v-model="option.hidden" label="Скрыть вариант" class="mt-3" :disabled="busy" :ui="{root:'items-center',container:'h-auto',label:'block'}"/></li></ul><UButton v-if="field&&selectedField?.valueType==='select'" icon="i-lucide-plus" color="neutral" variant="outline" class="mt-4" :disabled="busy" @click="add">Добавить вариант</UButton></section></template>
</template><template #footer><UButton color="neutral" variant="outline" :disabled="busy" @click="open=false">Закрыть</UButton><UButton v-if="editing" :disabled="busy||!name.trim()||!currentPreset" :loading="busy" @click="save">Сохранить настройки</UButton></template></UModal></template>
